      PregFaqPart(PregFaqSection.perspective, '', [
        'Low iron is genuinely common and very correctable; consistency with whatever plan your doctor gives you matters more than any single food or supplement choice.',
      ], []),
      PregFaqPart(PregFaqSection.takeaways, '', [], [
