    parts: [
      PregFaqPart(PregFaqSection.direct, '', [
        'Your baby will have their blood sugar checked several times in the first 12 to 24 hours after birth, since babies of mothers with gestational diabetes have a higher chance of their own blood sugar dropping right after delivery. Early, frequent breastfeeding genuinely helps stabilise this, and most babies do perfectly well.',
      ], []),
